update ${database.prefix.goods}hou_goods_article_info
set remark_num = remark_num + 1
where article_id in (

    #{articleId}

)

mapper.select:
SELECT ga.article_id, ga.article_title, ga.article_content, ga.article_cover, ga.audit_state, ga.audit_comment, ga.goods_id, ga.article_type, ga.create_time as postTime, uuu.user_mobile, uuu.user_name, uuu.user_nickname, ga.common_id, gmv.common_price, gmv.common_image, gmv.common_name, gt.tag_content, gt.tag_id, ga.create_time FROM goods_article_info ga LEFT JOIN ${database.prefix.userms}hou_user_info uuu ON ga.user_id = uuu.user_id LEFT JOIN ${database.prefix.goods}hou_goods_common gmv ON gmv.common_id=ga.common_id LEFT JOIN goods_tag_info gt ON ga.tag_id = gt.tag_id WHERE 1 =1
and ga.article_id= #{param.articleId}
and uuu.user_name =#{param.userName}
and ga.audit_state = #{param.auditState}
and ga.article_id=#{param.articleId}
order by ga.create_time desc

select a.article_id, a.article_title, a.article_content, a.article_cover, a.read_num, a.remark_num, a.like_num, a.star_num, a.user_id, a.article_type, a.audit_state, a.audit_comment, b.user_name from ${database.prefix.goods}hou_goods_article_info a inner join ${database.prefix.userms}hou_user_info b on a.user_id = b.user_id left join goods_tag_info c on a.tag_id = c.tag_id where 1=1
and ( c.tag_content LIKE CONCAT('%',#{param.queryStr},'%') or a.article_title LIKE CONCAT('%',#{param.queryStr},'%') or b.user_name LIKE CONCAT('%',#{param.queryStr},'%') )
and a.user_id = #{param.userId}
and a.audit_state = 1
and a.cat_id = #{param.catId}
and a.tag_id = #{param.tagId}
order by a.create_time desc

select a.article_id, a.article_title, a.article_content, a.article_cover, a.read_num, a.remark_num, a.like_num, a.star_num, a.user_id, a.article_type, a.audit_state, a.audit_comment, b.user_name from ${database.prefix.goods}hou_goods_article_info a inner join ${database.prefix.userms}hou_user_info b on a.user_id = b.user_id left join goods_tag_info c on a.tag_id = c.tag_id where a.audit_state = 1
and a.user_id not in (select followed_user_id from ${database.prefix.goods}hou_goods_article_user_follow uf where uf.follow_user_id = #{userId}) and a.user_id != #{userId}
GROUP BY a.user_id ORDER BY RAND() LIMIT 10

select count(1)
	from ${database.prefix.goods}hou_goods_article_user_follow
	where followed_user_id = #{param.userId}
